
/* ===== LOBBY: FSB OPERATOR (personagem principal) com a animação do próprio modelo =====
   Modelo "FSB Operator" por Mateusz Woliński (CC BY 4.0, Sketchfab) — esqueleto Mixamo, com fuzil.
   Entra como 1º personagem do lobby, já selecionado. Os outros 3 continuam na lista (setas ‹ ›).
   Se o modelo não carregar (sem internet), o lobby fica como antes. */
(function(){
'use strict';
const GLB64='';
let dead=false,ready=false,ROS=0;
const $=id=>document.getElementById(id);
const fail=e=>{dead=true;try{if(typeof FG!=='undefined')FG.visible=false}catch(_){}try{console.error('[lobby-fsb]',e)}catch(_){}try{if(typeof pg!=='undefined'&&pg)pg.visible=true}catch(_){}};
let FG=null;
const SRC=['https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/loaders/GLTFLoader.js','https://unpkg.com/three@0.128.0/examples/js/loaders/GLTFLoader.js','https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/examples/js/loaders/GLTFLoader.js'];
function load(i){return new Promise((res,rej)=>{if(typeof THREE!=='undefined'&&THREE.GLTFLoader)return res();if(i>=SRC.length)return rej(new Error('GLTFLoader indisponível'));const s=document.createElement('script');s.src=SRC[i];s.onload=()=>res();s.onerror=()=>{s.remove();load(i+1).then(res,rej)};document.head.appendChild(s)})}
function start(){
 try{
  if(typeof THREE==='undefined'||!THREE.GLTFLoader||typeof PS==='undefined'||typeof PR2==='undefined'||typeof LB==='undefined'||typeof showCh!=='function')return;
  const bin=atob(GLB64),u8=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i);
  const cib0=window.createImageBitmap;window.createImageBitmap=undefined;
  try{new THREE.GLTFLoader().parse(u8.buffer,'',gltf=>{
   try{
    const root=gltf.scene,clip=gltf.animations&&gltf.animations[0];if(!root||!clip)throw new Error('modelo sem animação');
    root.traverse(o=>{if(o.isMesh||o.isSkinnedMesh){o.frustumCulled=false;o.castShadow=false;o.receiveShadow=false;
     [].concat(o.material).forEach(m=>{if(!m)return;if(m.map){m.map.encoding=THREE.LinearEncoding;m.map.anisotropy=4}
      if(m.isMeshStandardMaterial){m.envMapIntensity=.6}m.needsUpdate=true})}});
    FG=new THREE.Group();FG.visible=false;FG.add(root);PS.add(FG);
    const mx=new THREE.AnimationMixer(root);mx.clipAction(clip).play();
    let lt=performance.now(),fy=0;
    const orn=PR2.render;
    PR2.render=function(s,c){
     if(!dead&&FG&&s===PS&&FG.visible){try{
      const n=performance.now();let dt=(n-lt)/1000;lt=n;if(!(dt>0)||dt>.1)dt=.016;
      mx.update(dt);fy+=((window.__lobbyYaw||0)-fy)*.25;FG.rotation.y=.18+fy}catch(e){fail(e)}}
     else lt=performance.now();
     return orn.apply(this,arguments)};
    /* ao começar a partida, devolve a memória da placa de vídeo usada pelo FSB (volta sozinha ao voltar ao lobby) */
    try{if(typeof R!=='undefined'){let gone=false;const rM=R.render;
     const free=()=>{root.traverse(o=>{try{if(o.geometry)o.geometry.dispose();[].concat(o.material||[]).forEach(m=>{['map','normalMap','metalnessMap','roughnessMap'].forEach(k=>{if(m[k])m[k].dispose()});m.dispose()})}catch(e){}})};
     R.render=function(){if(!dead){try{if(typeof started!=='undefined'){if(started&&!gone){gone=true;free()}else if(!started&&gone)gone=false}}catch(e){}}return rM.apply(this,arguments)}}}catch(e){}
    const osc=window.showCh;
    window.showCh=function(){const r=osc.apply(this,arguments);if(!dead)try{apply()}catch(e){fail(e)}return r};
    function apply(){
     const on=ROS===0&&ready;FG.visible=on;
     try{if(pg)pg.visible=!on}catch(e){}
     if(on){try{$('chn').textContent='FSB Operator';$('chs').textContent='Personagem';const nm=$('nm');if(nm)nm.textContent=nm.textContent.replace(/^.*?(?=\s[·\-–]\s)/,'FSB Operator')}catch(e){}}}
    const sel=()=>{LB.ch=ROS===0?0:ROS-1;showCh()};
    const nx=$('nx'),pl=$('pl');
    if(nx)nx.onclick=()=>{ROS=(ROS+1)%4;sel()};
    if(pl)pl.onclick=()=>{ROS=(ROS+3)%4;sel()};
    ready=true;sel();
    console.log('[lobby-fsb] ok');
   }catch(e){fail(e)}
  },err=>fail(err))}finally{window.createImageBitmap=cib0}
 }catch(e){fail(e)}
}
try{load(0).then(start,e=>fail(e))}catch(e){fail(e)}
})();

